function createWPDatalitics() {
  if (codeWpLink && endpointWpDatalitics) {
    var t = document.createElement("div");
    (t.className = "wp-datalitics"),
      (t.onclick = function () {
        let p = getCookie("params");
        p
          ? window.location.replace(
              `${endpointWpDatalitics}/${codeWpLink}${p}&isWpButtom=true`
            )
          : window.location.replace(
              `${endpointWpDatalitics}/${codeWpLink}?isWpButtom=true`
            );
      }),
      document.body.appendChild(t);
  }
}
document.addEventListener("DOMContentLoaded", createWPDatalitics);
